SELECT COUNT(*)
FROM cert
WHERE status = #{status}

SELECT id, user_id, cert_type, status, submitted_at, approved_at, expire_at,
       reject_reason, ocr_image_ref, fail_count, lock_until
FROM cert
WHERE status = #{status}
ORDER BY submitted_at ASC, id ASC
LIMIT #{limit} OFFSET #{offset}
